CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.core_fleet (id SERIAL PRIMARY KEY, name TEXT NOT NULL DEFAULT 'Стражи Ядра', ships TEXT NOT NULL DEFAULT '{}', total_attack INTEGER NOT NULL DEFAULT 0, total_defense INTEGER NOT NULL DEFAULT 0, pos_x NUMERIC NOT NULL DEFAULT 1200, pos_y NUMERIC NOT NULL DEFAULT 1200, status TEXT NOT NULL DEFAULT 'guarding', target_player_id INTEGER, tech_level INTEGER NOT NULL DEFAULT 10, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());